tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dlarfb, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function throws an error if provided an invalid `storev`', function test( t ) {
	var values;
	var V;
	var T;
	var C;
	var i;

	V = new Float64Array( 9 );
	T = new Float64Array( 9 );
	C = new Float64Array( 9 );

	values = [ 'foo', 'beep', 'boop', 5, null, void 0, [], {} ];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			dlarfb( 'left', 'transpose', 'forward', value, 3, 3, 3, V, 3, 1, 0, T, 3, 1, 0, C, 3, 1, 0, new Float64Array( 9 ), 3, 1, 0 );
		};
	}
});

